export type Strings = typeof ar;
export const STRINGS: Record<Lang, Strings> = { ar, en, ckb };
export const fill = (s: string, v: Record<string, string | number>) => s.replace(/\{(\w+)\}/g, (_, k) => String(v[k] ?? ''));
